import { hashString } from "./util.js";

function parseSizes(text) {
    if (!text)
        return [];
    return text.split(",").map((part) => part.trim().split("x").map(Number)).filter((pair) => pair.length === 2 && pair[0] > 0);
}

function matchBreakpoint(breakpoints) {
    for (const breakpoint of breakpoints) {
        if (window.matchMedia(breakpoint.media).matches)
            return breakpoint;
    }
    return null;
}

function intersectSizes(allowed, declared) {
    if (!declared.length)
        return allowed;
    const result = allowed.filter(([w, h]) => declared.some(([dw, dh]) => dw === w && dh === h));
    return result.length ? result : allowed;
}

function findContainer(name) {
    return document.getElementById("slot-" + name) || document.querySelector('[data-commercial-slot="' + name + '"]');
}

// Resolves the registered slot names against the conditional registry: a
// slot is active when its container is on the page and one of its
// breakpoints matches the viewport.
export function resolveSlots(config, registered) {
    const registry = config.conditionalRegistry;
    const definitions = registry.slots;
    const known = Object.keys(definitions);
    const slots = [];
    for (const name of registered) {
        if (!known.includes(name))
            continue;
        const definition = definitions[name];
        const element = findContainer(name);
        if (!element)
            continue;
        const breakpoint = matchBreakpoint(definition.breakpoints);
        if (!breakpoint)
            continue;
        const declared = parseSizes(element.getAttribute("data-commercial-sizes"));
        const lazyAttribute = element.getAttribute("data-commercial-lazy");
        slots.push({
            name,
            element,
            id: element.id || "slot-" + name,
            definition,
            sizes: intersectSizes(breakpoint.sizes, declared),
            lazy: lazyAttribute === null ? !!definition.lazy : lazyAttribute === "true",
            placements: Object.fromEntries(definition.bidders.map((bidder) => [bidder, String(hashString(name + bidder) % 90000 + 10000)])),
        });
    }
    return slots;
}
