const CLOCK_BASE = Date.UTC(2026, 10, 2, 7, 15, 0);

export function now() {
    return CLOCK_BASE + performance.now();
}

export function mulberry32(seed) {
    let state = seed >>> 0;
    return function () {
        let t = (state = (state + 0x6d2b79f5) >>> 0);
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

export function hashString(text) {
    let hash = 0x811c9dc5;
    for (let i = 0; i < text.length; i++)
        hash = Math.imul(hash ^ text.charCodeAt(i), 0x01000193);
    return hash >>> 0;
}

export function track(promise) {
    const work = window.__benchmarkWork;
    return work ? work.track(promise) : promise;
}

export function settled(name) {
    if (window.__benchmarkWork)
        window.__benchmarkWork.settled(name);
}

export function mark(name) {
    try {
        performance.mark("adtag-" + name);
    } catch (e) {}
}

export function nextTask() {
    return new Promise((resolve) => setTimeout(resolve, 0));
}

export function loadScript(src) {
    return track(
        new Promise((resolve) => {
            const script = document.createElement("script");
            script.async = true;
            script.src = src;
            script.onload = () => resolve(true);
            script.onerror = () => resolve(false);
            document.head.appendChild(script);
        })
    );
}

export function runSafe(callback) {
    return function (...args) {
        try {
            return callback.apply(this, args);
        } catch (error) {
            console.error("adtag:", error);
            return undefined;
        }
    };
}
