import { mark, track, settled, runSafe } from "./util.js";
import { resolveSlots } from "./registry.js";
import { waitForConsent } from "./consent.js";

const RELEASE = "1.0.0";

const registered = new Set();
let config = null;
let started = false;
let engine = null;

function configure(options) {
    mark("Phase-CONFIGURED-start");
    config = options.adtag || options;
    if (!config.conditionalRegistry || !config.conditionalRegistry.slots)
        throw new Error("adtag: missing conditionalRegistry");
    mark("Phase-CONFIGURED-end");
}

function registerSlots(names) {
    for (const name of names)
        registered.add(name);
}

async function run() {
    mark("Phase-SETUP-start");
    const slots = resolveSlots(config, registered);
    const enginePromise = import(/* webpackChunkName: "engine" */ "./engine.js");
    mark("Phase-SETUP-end");
    mark("Phase-waitForConsent-start");
    const consent = await waitForConsent();
    mark("Phase-waitForConsent-end");
    if (!slots.length)
        return;
    const { createEngine } = await enginePromise;
    engine = createEngine({ config, slots, consent });
    await engine.run();
    settled("adtag-render");
}

function start() {
    if (started || !config)
        return;
    started = true;
    track(run());
}

function refresh(name) {
    return engine ? engine.refresh(name) : Promise.resolve();
}

function install() {
    const api = window.adtag || (window.adtag = { cmd: [] });
    const queued = Array.isArray(api.cmd) ? api.cmd : [];
    api.version = RELEASE;
    api.configure = configure;
    api.registerSlots = registerSlots;
    api.start = start;
    api.refresh = refresh;
    api.cmd = {
        push(...callbacks) {
            for (const callback of callbacks)
                runSafe(callback)();
            return callbacks.length;
        },
    };
    for (const callback of queued)
        runSafe(callback)();
    settled("adtag");
}

install();
