export function waitForConsent() {
    return new Promise((resolve) => {
        const api = window.__tcfapi;
        if (typeof api !== "function") {
            resolve({ eventStatus: "unavailable" });
            return;
        }
        let done = false;
        api("addEventListener", 2, (data, success) => {
            if (done || !success || !data)
                return;
            const ready = data.eventStatus === "tcloaded" || data.eventStatus === "useractioncomplete" || data.gdprApplies === false;
            if (!ready)
                return;
            done = true;
            if (data.listenerId !== undefined)
                api("removeEventListener", 2, () => {}, data.listenerId);
            resolve(data);
        });
    });
}
